parameters.jsCode:
const body = $input.first().json.body;
const required = ['department', 'period', 'line_items'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.line_items) || body.line_items.length === 0) return [{ json: { valid: false, error: 'line_items must be a non-empty array' } }];
const items = body.line_items.map((item, i) => {
  const budgeted = parseFloat(item.budgeted);
  const actual = parseFloat(item.actual);
  if (isNaN(budgeted) || isNaN(actual)) return null;
  const variance = parseFloat((actual - budgeted).toFixed(2));
  const variancePct = budgeted !== 0 ? parseFloat(((variance / Math.abs(budgeted)) * 100).toFixed(1)) : null;
  const isOver = variance > 0;
  const isSignificant = variancePct !== null && Math.abs(variancePct) >= (parseFloat(body.significance_threshold) || 10);
  return {
    lineId: `L${String(i+1).padStart(3,'0')}`,
    category: (item.category || 'Uncategorized').trim(),
    description: (item.description || '').trim(),
    budgeted,
    actual,
    variance,
    variancePct,
    isOver,
    isSignificant,
    notes: (item.notes || '').slice(0, 200)
  };
}).filter(Boolean);
if (items.length === 0) return [{ json: { valid: false, error: 'No valid line items found' } }];
const totalBudgeted = items.reduce((s,i) => s + i.budgeted, 0);
const totalActual = items.reduce((s,i) => s + i.actual, 0);
const totalVariance = parseFloat((totalActual - totalBudgeted).toFixed(2));
const significantItems = items.filter(i => i.isSignificant);
return [{ json: {
  valid: true,
  department: body.department.trim(),
  period: body.period.trim(),
  currency: body.currency || 'USD',
  items,
  totalBudgeted: parseFloat(totalBudgeted.toFixed(2)),
  totalActual: parseFloat(totalActual.toFixed(2)),
  totalVariance,
  totalVariancePct: totalBudgeted !== 0 ? parseFloat(((totalVariance / Math.abs(totalBudgeted)) * 100).toFixed(1)) : null,
  significantItemCount: significantItems.length,
  significanceThreshold: parseFloat(body.significance_threshold) || 10,
  context: (body.context || '').slice(0, 600),
  recipientEmails: Array.isArray(body.recipient_emails) ? body.recipient_emails : (body.recipient_emails||'').split(',').map(e=>e.trim()).filter(Boolean),
  replyEmail: body.reply_email || null
} }];

values.content:
Analyze this budget variance report.

Department: {{ $json.department }}
Period: {{ $json.period }}
Currency: {{ $json.currency }}
Significance threshold: {{ $json.significanceThreshold }}%

Total budgeted: {{ $json.currency }}{{ $json.totalBudgeted }}
Total actual: {{ $json.currency }}{{ $json.totalActual }}
Total variance: {{ $json.currency }}{{ $json.totalVariance }} ({{ $json.totalVariancePct }}%)
Significant line items: {{ $json.significantItemCount }}

Context from department head:
{{ $json.context || 'none provided' }}

Line items with significant variance:
{{ $json.items.filter(i => i.isSignificant).map(i => i.lineId + ' ' + i.category + (i.description?' ('+i.description+')':'') + ': budgeted ' + $json.currency + i.budgeted + ', actual ' + $json.currency + i.actual + ', variance ' + (i.isOver?'+':'') + $json.currency + i.variance + ' (' + (i.isOver?'+':'') + i.variancePct + '%)' + (i.notes?' — '+i.notes:'')).join('\n') || 'none above threshold' }}

All line items:
{{ $json.items.map(i => i.lineId + ' ' + i.category + ': ' + (i.isOver?'+':'') + $json.currency + i.variance).join(', ') }}

Return this JSON:
{
  "overall_assessment": "2-3 sentences: what this variance picture tells us about the department's financial health this period",
  "variance_verdict": "one of: favorable | unfavorable | mixed | on_target",
  "key_drivers": [
    {"line_id": "L001", "driver": "what caused this variance", "is_concern": false, "is_one_time": true}
  ],
  "concerns": ["specific line items or patterns that require attention or investigation"],
  "positive_variances": ["favorable variances worth acknowledging"],
  "recommended_actions": [
    {"action": "specific recommendation", "urgency": "immediate | this_month | next_quarter", "owner": "department head | finance | leadership"}
  ],
  "forecast_implication": "if current trends continue, what does the full-year position look like",
  "questions_to_investigate": ["specific questions the department head should answer about the significant variances"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let analysis;
try { analysis = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate & Calculate').first().json;
analysis._data = input;
return [{ json: analysis }];

const a = $input.first().json;
const d = a._data;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function fmtV(v, cur) { return (v>0?'+':'')+cur+(Math.abs(v)).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); }
const verdictConfig = {favorable:{color:'#16a34a',bg:'#f0fdf4',label:'Favorable'},unfavorable:{color:'#dc2626',bg:'#fef2f2',label:'Unfavorable'},mixed:{color:'#d97706',bg:'#fffbeb',label:'Mixed'},on_target:{color:'#2563eb',bg:'#eff6ff',label:'On Target'}};
const vc = verdictConfig[a.variance_verdict] || verdictConfig.mixed;
const overallColor = d.totalVariance > 0 ? '#dc2626' : d.totalVariance < 0 ? '#16a34a' : '#6b7280';
const allRows = d.items.map(item => {
  const vc2 = item.isOver ? '#dc2626' : '#16a34a';
  return `<tr style="border-bottom:1px solid #f3f4f6${item.isSignificant?' background:#fafafa':''}">
    <td style="padding:8px 12px;font-size:12px;font-family:monospace;color:#9ca3af">${esc(item.lineId)}</td>
    <td style="padding:8px 12px;font-size:13px;font-weight:${item.isSignificant?'600':'400'}">${esc(item.category)}${item.description?`<div style="font-size:11px;color:#9ca3af">${esc(item.description)}</div>`:''}</td>
    <td style="padding:8px 12px;font-size:13px;text-align:right">${esc(d.currency)}${item.budgeted.toLocaleString()}</td>
    <td style="padding:8px 12px;font-size:13px;text-align:right">${esc(d.currency)}${item.actual.toLocaleString()}</td>
    <td style="padding:8px 12px;font-size:13px;text-align:right;font-weight:600;color:${vc2}">${fmtV(item.variance, d.currency)}</td>
    <td style="padding:8px 12px;font-size:12px;text-align:right;color:${vc2}">${item.variancePct!==null?(item.isOver?'+':'')+item.variancePct+'%':'—'}</td>
    <td style="padding:8px 12px;text-align:center">${item.isSignificant?'⚠':''}</td>
  </tr>`;
}).join('');
const concerns = (a.concerns||[]).map(c=>`<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #fef2f2;color:#7f1d1d">⚠ ${esc(c)}</div>`).join('');
const positives = (a.positive_variances||[]).map(p=>`<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f0fdf4;color:#166534">✓ ${esc(p)}</div>`).join('');
const actions = (a.recommended_actions||[]).map(ac => { const uc={immediate:'#dc2626',this_month:'#d97706',next_quarter:'#2563eb'}[ac.urgency]||'#6b7280'; return `<div style="border-left:3px solid ${uc};padding:8px 12px;background:#fafafa;border-radius:0 4px 4px 0;margin-bottom:6px"><div style="font-size:14px">${esc(ac.action)}</div><div style="font-size:11px;color:${uc};margin-top:2px">${esc(ac.urgency.replace(/_/g,' '))} · ${esc(ac.owner)}</div></div>`; }).join('');
const questions = (a.questions_to_investigate||[]).map((q,i)=>`<div style="font-size:13px;padding:6px 0;border-bottom:1px solid #eff6ff;color:#1e40af">${i+1}. ${esc(q)}</div>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:760px;margin:0 auto">
  <div style="background:#1e293b;color:#fff;padding:18px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;color:#64748b;margin-bottom:4px">Budget Variance · ${esc(d.period)}</div>
    <div style="font-size:19px;font-weight:700">${esc(d.department)}</div>
  </div>
  <div style="background:${vc.bg};padding:14px 28px;border:1px solid ${vc.color}44;border-top:none;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">
    <div><span style="background:${vc.color};color:#fff;font-size:12px;font-weight:700;padding:4px 14px;border-radius:12px">${vc.label}</span><p style="font-size:14px;color:#374151;margin:8px 0 0;line-height:1.6">${esc(a.overall_assessment)}</p></div>
    <div style="text-align:right;flex-shrink:0">
      <div style="font-size:11px;color:#9ca3af">Total variance</div>
      <div style="font-size:28px;font-weight:800;color:${overallColor}">${fmtV(d.totalVariance,d.currency)}</div>
      <div style="font-size:12px;color:#9ca3af">${d.totalVariancePct!==null?(d.totalVariance>0?'+':'')+d.totalVariancePct+'% vs budget':''}</div>
    </div>
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6;overflow-x:auto">
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f9fafb;font-size:11px;text-transform:uppercase;color:#9ca3af">
        <th style="padding:7px 12px;text-align:left">ID</th><th style="padding:7px 12px;text-align:left">Category</th>
        <th style="padding:7px 12px;text-align:right">Budget</th><th style="padding:7px 12px;text-align:right">Actual</th>
        <th style="padding:7px 12px;text-align:right">Variance</th><th style="padding:7px 12px;text-align:right">%</th>
        <th style="padding:7px 12px;text-align:center">!</th>
      </tr></thead>
      <tbody>${allRows}</tbody>
      <tfoot><tr style="background:#f9fafb;font-weight:700">
        <td colspan="2" style="padding:9px 12px;font-size:14px">Total</td>
        <td style="padding:9px 12px;text-align:right">${esc(d.currency)}${d.totalBudgeted.toLocaleString()}</td>
        <td style="padding:9px 12px;text-align:right">${esc(d.currency)}${d.totalActual.toLocaleString()}</td>
        <td style="padding:9px 12px;text-align:right;color:${overallColor}">${fmtV(d.totalVariance,d.currency)}</td>
        <td style="padding:9px 12px;text-align:right;color:${overallColor}">${d.totalVariancePct!==null?(d.totalVariance>0?'+':'')+d.totalVariancePct+'%':'—'}</td>
        <td></td>
      </tr></tfoot>
    </table>
  </div>
  ${concerns||positives?`<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">${concerns?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#dc2626;margin-bottom:7px">Concerns</div>${concerns}</div>`:''  }${positives?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#16a34a;margin-bottom:7px">Positive variances</div>${positives}</div>`:''  }</div></div>`:''}
  ${actions?`<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Recommended actions</div>${actions}</div>`:''}
  ${a.forecast_implication?`<div style="background:#eff6ff;padding:12px 28px;border:1px solid #bfdbfe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:5px">Forecast implication</div><div style="font-size:14px;color:#1e40af;line-height:1.65">${esc(a.forecast_implication)}</div></div>`:''}
  ${questions?`<div style="background:#fff;padding:12px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px">Questions to investigate</div>${questions}</div>`:''}
  <div style="background:#1e293b;color:#475569;font-size:11px;padding:10px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Budget Variance · ${esc(d.department)} · ${esc(d.period)}</div>
</div></body></html>`;
return [{ json: { html, recipients: [...new Set([...d.recipientEmails, d.replyEmail].filter(Boolean))], department: d.department, period: d.period, verdict: a.variance_verdict, totalVariance: d.totalVariance, currency: d.currency, analysis: a } }];
